"""Leakage checks on the split CSVs committed under splits/ (regenerated by `make metadata`)."""

from pathlib import Path

import pandas as pd
import pytest

ROOT = Path(__file__).resolve().parent.parent
SPLITS = sorted((ROOT / "splits").glob("*.csv"))


def test_split_files_exist():
    assert (ROOT / "splits" / "nih.csv").exists()


@pytest.mark.parametrize("csv", SPLITS, ids=[p.stem for p in SPLITS])
def test_every_image_once_and_no_patient_straddles_splits(csv):
    df = pd.read_csv(csv, dtype=str)
    assert list(df.columns) == ["image_id", "patient_id", "split"]
    assert df["image_id"].is_unique
    assert set(df["split"]) == {"train", "val", "test"}
    assert (df.groupby("patient_id")["split"].nunique() == 1).all()


@pytest.mark.skipif(
    not (ROOT / "datasets/nih/meta/test_list.txt").exists(), reason="NIH data absent"
)
def test_nih_test_split_is_exactly_the_official_test_list():
    df = pd.read_csv(ROOT / "splits/nih.csv", dtype=str)
    official = {
        x.removesuffix(".png")
        for x in (ROOT / "datasets/nih/meta/test_list.txt").read_text().split()
    }
    assert set(df.loc[df["split"] == "test", "image_id"]) == official
